package cn.iocoder.yudao.framework.dbswitch.data;

import cn.iocoder.yudao.framework.dbswitch.common.config.DbSwitchOptions;
import cn.iocoder.yudao.framework.dbswitch.common.entity.PatternMapper;
import cn.iocoder.yudao.framework.dbswitch.common.type.ProductTypeEnum;
import cn.iocoder.yudao.framework.dbswitch.data.config.MigrationRequest;
import cn.iocoder.yudao.framework.dbswitch.data.domain.DbSwitchResult;
import cn.iocoder.yudao.framework.dbswitch.data.entity.SourceDataSourceProperties;
import cn.iocoder.yudao.framework.dbswitch.data.runtime.DbSwitchRuntime;
import cn.iocoder.yudao.framework.dbswitch.data.service.MigrationService;
import cn.iocoder.yudao.framework.dbswitch.product.doris.*;
import cn.iocoder.yudao.framework.dbswitch.spi.DbSwitchProductRegistry;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfSystemProperty;
import java.sql.*;
import java.math.*;
import java.util.*;
import java.lang.reflect.*;
import static org.junit.jupiter.api.Assertions.*;

/** Public MigrationService against explicit disposable Doris 4.0, including its native UNIQUE model. */
@Timeout(180)
@EnabledIfSystemProperty(named="datahub.test.doris.url",matches="jdbc:mysql://127[.]0[.]0[.]1:[0-9]+/")
class MigrationDorisTest {
    private Connection control;private String schema;
    @BeforeEach void setup()throws Exception {control=DriverManager.getConnection(url(),"root","");try(var s=control.createStatement();var r=s.executeQuery("SHOW FRONTENDS")){assertTrue(r.next());assertTrue(r.getString("Version").startsWith("doris-4.0.8"));}schema="migration_"+UUID.randomUUID().toString().replace("-","");sql("CREATE DATABASE "+schema);}
    @AfterEach void cleanup()throws Exception {if(control!=null)try(var owned=control){if(schema!=null)sql("DROP DATABASE "+schema+" FORCE");}}
    @Test void fullThenDifferenceAndNoChangeReplayPreserveExactNativeValues()throws Exception {
        create("source_rows","UNIQUE");create("target_rows","UNIQUE");seed("source_rows");var full=run("source_rows","target_rows",false,false);success(full);assertEquals(503,full.getTableResultList().getFirst().getTransferSummary().acknowledgedRows());equalRows("source_rows","target_rows");
        sql("DELETE FROM "+table("source_rows")+" WHERE id=9007199254740993");sql("UPDATE "+table("source_rows")+" SET amount=-0.000000000000000001,note='changed' WHERE id=9007199254740994");sql("INSERT INTO "+table("source_rows")+" (part,id,amount,large_value) VALUES(1,9223372036854775807,99999999999999999999.999999999999999999,170141183460469231731687303715884105727)");
        success(run("source_rows","target_rows",true,false));equalRows("source_rows","target_rows");success(run("source_rows","target_rows",true,false));equalRows("source_rows","target_rows");
    }
    @Test void autoCreatePreservesUniqueModelAndOriginalValues()throws Exception {create("source_rows","UNIQUE");seed("source_rows");success(run("source_rows","created_rows",false,false));equalRows("source_rows","created_rows");assertEquals(shape("source_rows"),shape("created_rows"));}
    @Test void duplicateFullRetainsDuplicateRowsAndAutoCreatesDuplicateModel()throws Exception {create("source_rows","DUPLICATE");sql("INSERT INTO "+table("source_rows")+"(part,id,note) VALUES(1,1,'a'),(1,1,'b'),(1,2,NULL)");success(run("source_rows","created_rows",false,false));equalRows("source_rows","created_rows");assertFalse(shape("created_rows").unique());}
    @Test void explicitTruncateFullUsesTheExistingTableWithNewPartitions()throws Exception {create("source_rows","UNIQUE");create("target_rows","UNIQUE");sql("INSERT INTO "+table("source_rows")+"(part,id,note) VALUES(1,1,'source')");sql("INSERT INTO "+table("target_rows")+"(part,id,note) VALUES(1,9,'obsolete')");var request=request("source_rows","target_rows",false);request.getTarget().setTargetTruncateData(true);success(execute(request,false));equalRows("source_rows","target_rows");}
    @Test void emptyAutoCreateRetainsStructureWithoutInventingRows()throws Exception {create("source_rows","UNIQUE");success(run("source_rows","created_rows",false,false));assertEquals(shape("source_rows"),shape("created_rows"));assertEquals(0,rows("created_rows").size());}
    @Test void onlyCreateRetainsDefaultsAndComments()throws Exception {create("source_rows","UNIQUE");var request=request("source_rows","created_rows",false);request.getTarget().setOnlyCreate(true);success(execute(request,false));assertEquals(shape("source_rows"),shape("created_rows"));assertEquals(0,rows("created_rows").size());}
    @Test void nativeQuotedCommentsRoundTripAndRestoreNoBackslashEscapes()throws Exception {
        String comment="中文 'single' \"double\" \\ path\\notes\nline";
        String columnComment="中文 'single' \"double\"\nline";
        String literal=cn.iocoder.yudao.framework.dbswitch.product.doris.DorisNativeSchema.literal(comment);
        String columnLiteral=cn.iocoder.yudao.framework.dbswitch.product.doris.DorisNativeSchema.columnCommentLiteral(columnComment);
        assertThrows(IllegalArgumentException.class,()->cn.iocoder.yudao.framework.dbswitch.product.doris.DorisNativeSchema.columnCommentLiteral(comment));
        sql("CREATE TABLE "+table("source_rows")+"(id BIGINT NOT NULL,note VARCHAR(100) COMMENT "+columnLiteral+") UNIQUE KEY(id) COMMENT "+literal+" DISTRIBUTED BY HASH(id) BUCKETS 1 PROPERTIES('replication_num'='1')");
        var ds=new org.springframework.jdbc.datasource.SingleConnectionDataSource(control,true);
        var definition=DorisNativeTables.describe(ds,schema,"source_rows",20);
        sql("SET sql_mode='ANSI_QUOTES,NO_BACKSLASH_ESCAPES'");String original=sqlMode();
        try {
            DorisNativeTables.plan(ds,definition,schema,"created_rows",Map.of("id","id","note","note"),false,20).execute();
            assertEquals(original,sqlMode());assertEquals(comment,shape("created_rows").comment());
            assertEquals(columnComment,shape("created_rows").columns().get(1).comment());
        } finally {sql("SET sql_mode=DEFAULT");}
    }
    @Test void sourceCannotBeReplacedThroughAnotherConnectionDefaultCatalog()throws Exception {create("source_rows","UNIQUE");sql("INSERT INTO "+table("source_rows")+"(part,id) VALUES(1,1)");var source=new org.springframework.jdbc.datasource.DriverManagerDataSource(url(),"root","");var target=new org.springframework.jdbc.datasource.DriverManagerDataSource(url()+schema,"root","");var definition=DorisNativeTables.describe(source,schema,"source_rows",20);var mapping=new LinkedHashMap<String,String>();definition.fields().forEach(f->mapping.put(f,f));assertThrows(IllegalStateException.class,()->DorisNativeTables.plan(target,definition,schema,"source_rows",mapping,true,20));assertEquals(1,rows("source_rows").size());}
    @Test void decimalOverflowRejectsWholeBatchBeforeFirstRow()throws Exception {create("target_rows","UNIQUE");var source=new org.springframework.jdbc.datasource.DriverManagerDataSource(url(),"root","");var writer=new cn.iocoder.yudao.framework.dbswitch.dbwriter.doris.DorisWriterImpl(source);writer.configure(options(false));var fields=List.of("part","id","amount");writer.prepareWrite(schema,"target_rows",fields);assertThrows(IllegalArgumentException.class,()->writer.write(fields,Arrays.asList(new Object[]{1,1L,BigDecimal.ONE},new Object[]{1,2L,new BigDecimal("0.0000000000000000001")})));assertEquals(0,rows("target_rows").size());}
    @Test void duplicateSortKeysDoNotMasqueradeAsNativeUniqueKeys()throws Exception {create("source_rows","DUPLICATE");assertEquals(List.of(),DbSwitchProductRegistry.discover().metadata(ProductTypeEnum.DORIS).queryTablePrimaryKeys(control,schema,"source_rows"));var sync=new cn.iocoder.yudao.framework.dbswitch.dbsynch.doris.DorisDatabaseSyncImpl(new org.springframework.jdbc.datasource.DriverManagerDataSource(url(),"root",""));assertThrows(IllegalStateException.class,()->sync.prepare(schema,"source_rows",List.of("part","id","note"),List.of("part","id")));}
    @Test void acknowledgedMutationCountZeroRequiresExactVisibleState()throws Exception {create("target_rows","UNIQUE");sql("INSERT INTO "+table("target_rows")+"(part,id,note) VALUES(1,2,'old')");var sync=new cn.iocoder.yudao.framework.dbswitch.dbsynch.doris.DorisDatabaseSyncImpl(faultSource(false,true));sync.configure(options(false));sync.prepare(schema,"target_rows",List.of("part","id","note"),List.of("part","id"));assertEquals(1,sync.executeUpdate(Collections.singletonList(new Object[]{1,2L,"changed"})));assertEquals("changed",rows("target_rows").getFirst().get(3));assertEquals(1,sync.executeDelete(Collections.singletonList(new Object[]{1,2L,"changed"})));assertEquals(0,rows("target_rows").size());}
    @Test void realServerInsertWithLostAcknowledgementDoesNotRetry()throws Exception {create("target_rows","UNIQUE");var writer=new cn.iocoder.yudao.framework.dbswitch.dbwriter.doris.DorisWriterImpl(faultSource(true,false));writer.configure(options(false));var fields=List.of("part","id","note");writer.prepareWrite(schema,"target_rows",fields);var failure=assertThrows(cn.iocoder.yudao.framework.dbswitch.dbwriter.PartialBatchWriteException.class,()->writer.write(fields,Collections.singletonList(new Object[]{1,2L,"secret-value"})));assertEquals(0,failure.acknowledgedRows());assertEquals(1,failure.unknownRows());assertFalse(failure.terminationConfirmed());assertNull(failure.getCause());assertFalse(failure.toString().contains("secret-value"));assertEquals(1,rows("target_rows").size());}
    @Test void nativeLargeIntegerMinNullEmptyAndLiteralNullRemainDistinct()throws Exception {create("source_rows","UNIQUE");try(var s=control.prepareStatement("INSERT INTO "+table("source_rows")+"(part,id,note,large_value) VALUES(?,?,?,?)")){String[] texts={null,"","NULL","\\N","中文'\\\n\0😀"};for(int i=0;i<texts.length;i++){s.setInt(1,1);s.setLong(2,i);s.setString(3,texts[i]);s.setBigDecimal(4,new BigDecimal(BigInteger.ONE.shiftLeft(127).negate()));assertEquals(1,s.executeUpdate());}}success(run("source_rows","created_rows",false,false));equalRows("source_rows","created_rows");assertEquals(new BigDecimal(BigInteger.ONE.shiftLeft(127).negate()),rows("created_rows").getFirst().get(4));}
    @Test void nativeWriterRestoresPooledSessionSettings()throws Exception {create("target_rows","UNIQUE");sql("SET enable_insert_strict=false,enable_unique_key_partial_update=true,group_commit='async_mode'");try{var writer=new cn.iocoder.yudao.framework.dbswitch.dbwriter.doris.DorisWriterImpl(new org.springframework.jdbc.datasource.SingleConnectionDataSource(control,true));writer.configure(options(false));var fields=List.of("part","id","note");writer.prepareWrite(schema,"target_rows",fields);assertEquals(1,writer.write(fields,Collections.singletonList(new Object[]{1,1L,"session"})));try(var s=control.createStatement();var r=s.executeQuery("SELECT @@enable_insert_strict,@@enable_unique_key_partial_update,@@group_commit")){assertTrue(r.next());assertFalse(r.getBoolean(1));assertTrue(r.getBoolean(2));assertEquals("async_mode",r.getString(3));}}finally{sql("SET enable_insert_strict=true,enable_unique_key_partial_update=false,group_commit='off_mode'");}}
    @Test void nativePlanPreservesCatalogEscapesAndQuotedKeywords()throws Exception {sql("CREATE TABLE "+table("source_rows")+"(`key` BIGINT NOT NULL,`value` VARCHAR(100) DEFAULT 'quote\\\'\\\\end' COMMENT 'line\\nquote\\\'\\\\end') ENGINE=OLAP UNIQUE KEY(`key`) COMMENT 'table\\\'\\\\end' DISTRIBUTED BY HASH(`key`) BUCKETS 1 PROPERTIES('replication_num'='1')");
        // Doris 4.0.8 itself cannot evaluate this catalog default on the ORIGINAL source.
        // Preserve its definition and explicit values, without claiming to repair that server bug.
        SQLException sourceFailure=assertThrows(SQLException.class,()->sql("INSERT INTO "+table("source_rows")+"(`key`) VALUES(1)"));
        var ds=new org.springframework.jdbc.datasource.DriverManagerDataSource(url(),"root","");var definition=DorisNativeTables.describe(ds,schema,"source_rows",20);var plan=DorisNativeTables.plan(ds,definition,schema,"select",Map.of("key","order","value","where"),false,20);plan.execute();assertEquals(shape("source_rows").map(Map.of("key","order","value","where")),shape("select"));
        SQLException targetFailure=assertThrows(SQLException.class,()->sql("INSERT INTO "+table("select")+"(`order`) VALUES(1)"));assertEquals(sourceFailure.getSQLState(),targetFailure.getSQLState());
        try(var p=control.prepareStatement("INSERT INTO "+table("select")+"(`order`,`where`) VALUES(?,?)")){p.setLong(1,1);p.setString(2,"quote'\\end");assertEquals(1,p.executeUpdate());}
        try(var s=control.createStatement();var r=s.executeQuery("SELECT `where` FROM "+table("select"))){assertTrue(r.next());assertEquals("quote'\\end",r.getString(1));}}
    @Test void nativePlanRejectsTargetRebuildAfterPreflightBeforeAnyReplacement()throws Exception {create("source_rows","UNIQUE");create("target_rows","UNIQUE");var ds=new org.springframework.jdbc.datasource.DriverManagerDataSource(url(),"root","");var definition=DorisNativeTables.describe(ds,schema,"source_rows",20);var fields=new LinkedHashMap<String,String>();definition.fields().forEach(f->fields.put(f,f));var plan=DorisNativeTables.plan(ds,definition,schema,"target_rows",fields,true,20);assertTrue(plan.requiresExclusiveDdlOwnership());sql("DROP TABLE "+table("target_rows")+" FORCE");create("target_rows","UNIQUE");sql("INSERT INTO "+table("target_rows")+"(part,id,note) VALUES(1,1,'sentinel')");assertThrows(IllegalStateException.class,plan::execute);assertEquals("sentinel",rows("target_rows").getFirst().get(3));}
    @Test void nativeDdlAndPreparedValuesRestoreNoBackslashEscapeMode()throws Exception {create("source_rows","UNIQUE");var ds=new org.springframework.jdbc.datasource.SingleConnectionDataSource(control,true);var definition=DorisNativeTables.describe(ds,schema,"source_rows",20);var mapping=new LinkedHashMap<String,String>();definition.fields().forEach(f->mapping.put(f,f));sql("SET sql_mode='ANSI_QUOTES,NO_BACKSLASH_ESCAPES'");String original=sqlMode();try{DorisNativeTables.plan(ds,definition,schema,"created_rows",mapping,false,20).execute();assertEquals(original,sqlMode());var writer=new cn.iocoder.yudao.framework.dbswitch.dbwriter.doris.DorisWriterImpl(ds);writer.configure(options(false));var fields=List.of("part","id","note");writer.prepareWrite(schema,"created_rows",fields);String text="中文'\\\n\0😀";assertEquals(1,writer.write(fields,Collections.singletonList(new Object[]{1,1L,text})));assertEquals(original,sqlMode());assertEquals(text,rows("created_rows").getFirst().get(3));}finally{sql("SET sql_mode=DEFAULT");}}
    private String sqlMode()throws Exception {try(var s=control.createStatement();var r=s.executeQuery("SELECT @@sql_mode")){assertTrue(r.next());return r.getString(1);}}
    @Test void zeroCountWithoutVisibleMutationIsUnknownRatherThanSuccess()throws Exception {create("target_rows","UNIQUE");sql("INSERT INTO "+table("target_rows")+"(part,id,note) VALUES(1,2,'old')");var sync=new cn.iocoder.yudao.framework.dbswitch.dbsynch.doris.DorisDatabaseSyncImpl(faultSource(false,true,true));sync.configure(options(false));sync.prepare(schema,"target_rows",List.of("part","id","note"),List.of("part","id"));var failure=assertThrows(cn.iocoder.yudao.framework.dbswitch.dbwriter.PartialBatchWriteException.class,()->sync.executeUpdate(Collections.singletonList(new Object[]{1,2L,"changed"})));assertEquals(0,failure.acknowledgedRows());assertEquals(1,failure.unknownRows());assertEquals("old",rows("target_rows").getFirst().get(3));}
    private javax.sql.DataSource faultSource(boolean lose,boolean zero){return faultSource(lose,zero,false);}
    private javax.sql.DataSource faultSource(boolean lose,boolean zero,boolean skip) {
        return new org.springframework.jdbc.datasource.AbstractDataSource(){@Override public Connection getConnection()throws SQLException{return wrap(DriverManager.getConnection(url(),"root",""));}@Override public Connection getConnection(String user,String pass)throws SQLException{return getConnection();}
            private Connection wrap(Connection actual){return (Connection)Proxy.newProxyInstance(Connection.class.getClassLoader(),new Class<?>[]{Connection.class},(p,m,a)->{Object result=invoke(m,actual,a);if(result instanceof PreparedStatement statement&&m.getName().equals("prepareStatement")&&((String)a[0]).matches("(?s)^(INSERT|UPDATE|DELETE).*")){return Proxy.newProxyInstance(PreparedStatement.class.getClassLoader(),new Class<?>[]{PreparedStatement.class},(q,method,args)->{if(skip&&method.getName().equals("executeUpdate"))return 0;Object answer=invoke(method,statement,args);if(method.getName().equals("executeUpdate")){if(lose)throw new SQLException("secret-response");if(zero)return 0;}return answer;});}return result;});}
        };
    }
    private static Object invoke(Method method,Object target,Object[] args)throws Throwable{try{return method.invoke(target,args);}catch(InvocationTargetException failure){throw failure.getCause();}}
    private void create(String name,String model)throws Exception {sql("CREATE TABLE "+table(name)+"(part SMALLINT NOT NULL,id BIGINT NOT NULL,amount DECIMAL(38,18),note VARCHAR(256) DEFAULT 'plain' COMMENT 'notes',large_value LARGEINT,event_time DATETIME(6),day DATE) ENGINE=OLAP "+model+" KEY(part,id) DISTRIBUTED BY HASH(part,id) BUCKETS 1 PROPERTIES('replication_num'='1')");}
    private void seed(String name)throws Exception {try(var s=control.prepareStatement("INSERT INTO "+table(name)+" VALUES "+String.join(",",Collections.nCopies(503,"(?,?,?,?,?,?,?)")))){s.setQueryTimeout(30);for(int i=0;i<503;i++){int b=i*7;s.setInt(b+1,i%2);s.setLong(b+2,9007199254740993L+i);s.setBigDecimal(b+3,i%3==0?null:new BigDecimal("12345678901234567890.123456789012345678"));s.setString(b+4,i%3==0?null:"中文'\\\n😀"+i);s.setBigDecimal(b+5,i%3==0?null:new BigDecimal("170141183460469231731687303715884105727"));s.setTimestamp(b+6,Timestamp.valueOf("2026-10-03 12:34:56.123456"));s.setDate(b+7,java.sql.Date.valueOf("2026-10-03"));}assertEquals(503,s.executeUpdate());}}
    private MigrationRequest request(String sourceTable,String targetTable,boolean diff){var request=new MigrationRequest();var source=new SourceDataSourceProperties();source.setSourceProductType(ProductTypeEnum.DORIS);source.setUrl(url());source.setUsername("root");source.setPassword("");source.setSourceSchema(schema);source.setSourceIncludes(sourceTable);source.setPoolSize(1);source.setFetchSize(500);source.setRegexTableMapper(List.of(new PatternMapper("^"+sourceTable+"$",targetTable)));request.getSource().add(source);
        var target=request.getTarget();target.setTargetProductType(ProductTypeEnum.DORIS);target.setUrl(url());target.setUsername("root");target.setPassword("");target.setTargetSchema(schema);target.setPoolSize(1);target.setWriterEngineInsert(true);target.setChangeDataSync(diff);if(diff)target.setChangeDataSyncType("PK_ORDER_COMPARE");return request;}
    private DbSwitchResult run(String source,String target,boolean diff,boolean stream)throws Exception{return execute(request(source,target,diff),stream);}
    private DbSwitchResult execute(MigrationRequest request,boolean stream)throws Exception{try(var runtime=new DbSwitchRuntime(DbSwitchProductRegistry.discover(),options(stream),null)){return new MigrationService(request,ignored->{},null,runtime).run();}}
    private static DbSwitchOptions options(boolean stream){return new DbSwitchOptions(128L*1024*1024,true,stream,30,0,300000,30000,0);}
    private DorisNativeSchema.Table shape(String name)throws Exception {return DorisJdbcSupport.inspect(control,schema,name,30).table();}
    private void equalRows(String left,String right)throws Exception {assertEquals(rows(left),rows(right));}
    private List<List<Object>> rows(String name)throws Exception {var result=new ArrayList<List<Object>>();try(var s=control.createStatement();var r=s.executeQuery("SELECT part,id,amount,note,large_value,event_time,day FROM "+table(name)+" ORDER BY part,id,note")){while(r.next()){String large=r.getString(5);result.add(Arrays.asList(r.getInt(1),r.getLong(2),r.getBigDecimal(3),r.getString(4),large==null?null:new BigDecimal(large),r.getTimestamp(6),r.getDate(7)));}}return result;}
    private String table(String name){return DorisNativeSchema.relation(schema,name);}
    private void sql(String sql)throws Exception {try(var s=control.createStatement()){s.setQueryTimeout(30);s.execute(sql);}}
    private static String url(){return System.getProperty("datahub.test.doris.url");}
    private static void success(DbSwitchResult result){assertEquals(1,result.getTableResultList().size());assertTrue(result.getIfAllSuccess().get(),()->result.getTableResultList().toString());}
}
